  "q": "あるサービスデスクでは，電子メールによる問合せに対応しており，受付担当者がメールの内容を確認し，回答担当者の割当てをしていた。このたび，割当て業務の効率化を目的に，自動割当てツールを導入した。自動割当てツールは，メールの内容を基に自動で回答担当者の割当てを行うが，割当てができないことや割当てミスをすることがあり，それらについては，人手で対応している。導入前及び導入半年後の状況が次のとき，割当ての時間はサービスデスク全体で何％削減できたか。ここで，割当ての時間の削減率（％）は小数第1位を四捨五入するものとする。〔導入前〕問合せ件数 1,000件／日，割当ての時間 2分／件。〔導入半年後〕問合せ件数 1,000件／日，自動割当てができた割合 90％（割当ての時間 0分／件），うち，割当てミスの割合 5％（割当ての時間 4分／件），自動割当てができなかった割合 10％（割当ての時間 2分／件）",
