  "e": "使用量をタイムリーに把握し，容量不足の兆候を早期に検知できるようにする c は，マネジメントの仕組みそのものの改善に当たります。a は応急対応であるインシデント管理，b は原因特定と再発防止を行う問題管理，d は個別の対処です。",
  "src": "出典:IPA「ITパスポート試験 公開問題」令和8年度 問48",
