  "q": "次の表の作業を3名で実施するとき，全ての作業を終わらせるのに必要な最短の日数は何日か。ここで，複数要員が必要な作業は全員がそろわないと着手できず，指定された要員数以上の要員を充てても所要日数は短縮できない。また，着手した作業は作業が完了するまで中断できないものとする。〔表〕作業A：前提作業なし，要員数1名，所要日数3日。作業B：前提作業A，要員数2名，所要日数3日。作業C：前提作業A，要員数2名，所要日数3日。作業D：前提作業B，要員数1名，所要日数3日。作業E：前提作業C，要員数2名，所要日数3日。作業F：前提作業D，E，要員数1名，所要日数3日",
