  "q": "ある組織では過去には全員出社して業務を遂行していたが，現在は出社とテレワークの両方を使い分けて業務を遂行している。この組織において，ファシリティマネジメントの観点で改善を図っている事例として，適切なものだけを全て挙げたものはどれか。a 従業員の PC にインストールされた Web 会議用のソフトウェアを常に最新にし，Web 会議における利便性及びセキュリティを向上させる。　b 執務室のレイアウト変更や大画面の TV 会議室の設置を行い，従業員間のコミュニケーションを取りやすくする。　c 出社率を踏まえてフリーアドレスエリアの割合を増加し，オフィスを縮小させる。　d 短時間勤務や自宅外での業務を可能とする制度を導入し，様々な従業員が業務に参画しやすくする。",
