  "q": "関係データベースで管理している“学生”表，“科目”表，“成績”表がある。1人の学生は複数の科目を履修するものとし，“学生”表に登録されていない学生や，“科目”表に登録されていない科目は“成績”表に登録できないものとするとき，外部キーとして設定するのが適切なものはどれか。ここで，表中の下線は主キーを表す。〔“学生”表〕列：学生番号（主キー），学生名。行：G001，鈴木 次郎／G002，山田 春子。〔“科目”表〕列：科目コード（主キー），科目名。行：K001，データベース／K002，コンピュータ／K003，ネットワーク。〔“成績”表〕列：学生番号（主キー），科目コード（主キー），成績。行：G001，K001，優／G001，K002，可／G002，K002，良／G002，K003，優",
