  "q": "関数 isPrime は、引数として与えられた正の整数が、素数であれば true を、素数でなければ false を戻り値とする。例えば、関数 isPrime を isPrime(2)として呼び出したときの戻り値は true である。プログラム中の a、b に入れる字句の適切な組合せはどれか。〔プログラム〕○論理型： isPrime（整数型： num）／整数型： div ← 2／if（num が 2〔a〕）return false／else while（num が div〔b〕）if（num ÷ div の余り が 0 と等しい）return false else div ← div ＋ 1 endif／endwhile return true／endif",
