  "q": "4個の要素から成るデータの並びを、次の手順を繰り返して昇順に整列するとき、整列が終了するまでに(1)から(3)の一連の手順は、何回実行されるか。ここで、最初はデータの並び全体を整列対象とする。データの並び：[27, 42, 33, 12] 〔手順〕(1) 整列対象中の要素の最大の値を選び、最後の要素と入れ替える。(2) 最後の要素を整列対象から外す。(3) 整列対象に要素が1個以上残っていれば、(1)から(3)の一連の手順を実行する。残っていなければ、整列完了なので終了する。",
  "c": [
   "4",
   "2",
   "3",
   "5"
  ],
  "e": "1回の手順ごとに整列対象が1個ずつ減ります。対象が4個、3個、2個、1個のときに手順が実行され、対象が1個のときの手順の後に対象が0個になって終了するので、合計4回実行されます。",
  "src": "出典:IPA「ITパスポート試験 公開問題」令和7年度 問98",
